Here are both approaches:

## 1. Route Registration (AppShell.xaml.cs)

```csharp
public partial class AppShell : Shell
{
    public AppShell()
    {
        InitializeComponent();
        Routing.RegisterRoute("productdetails", typeof(ProductDetailsPage));
    }
}
```

## 2. ProductListPage — Navigate on Selection

```csharp
// Approach A: Pass product ID as query string
async void OnProductSelected(object sender, SelectionChangedEventArgs e)
{
    if (e.CurrentSelection.FirstOrDefault() is Product product)
    {
        await Shell.Current.GoToAsync($"productdetails?id={product.Id}");
        ((CollectionView)sender).SelectedItem = null;
    }
}

// Approach B: Pass full Product object
async void OnProductSelected(object sender, SelectionChangedEventArgs e)
{
    if (e.CurrentSelection.FirstOrDefault() is Product product)
    {
        var parameters = new ShellNavigationQueryParameters
        {
            { "product", product }
        };
        await Shell.Current.GoToAsync("productdetails", parameters);
        ((CollectionView)sender).SelectedItem = null;
    }
}
```

## 3. ProductDetailsViewModel — Receive Both via IQueryAttributable

```csharp
public partial class ProductDetailsViewModel : ObservableObject, IQueryAttributable
{
    [ObservableProperty]
    private string productId;

    [ObservableProperty]
    private Product product;

    public void ApplyQueryAttributes(IDictionary<string, object> query)
    {
        // Approach A: string parameter from query string
        if (query.TryGetValue("id", out var id))
        {
            ProductId = id.ToString();
            // Load full product from a service using the ID
        }

        // Approach B: full object from ShellNavigationQueryParameters
        if (query.TryGetValue("product", out var obj) && obj is Product p)
        {
            Product = p;
            ProductId = p.Id;
        }
    }
}
```

**Key points:**
- String params use the query string syntax (`?id=123`)
- Complex objects use `ShellNavigationQueryParameters` (no serialization needed)
- `IQueryAttributable` on the ViewModel handles both in one method
- Always `await` `GoToAsync` and clear `SelectedItem` to allow re-selection
